  for (var i = 0; i < STOP_CODES.length; i++) {
    if (key && key.indexOf(STOP_CODES[i][0]) >= 0) return { code: STOP_CODES[i][1], name: STOP_CODES[i][2] || stopTown(lead), time: p.time || '' };
  }
  var town = stopTown(lead), letters = town.replace(/[^A-Za-z]/g, '');
