/* Default language is NEPALI (main market focus) — first-time visitors see
   ने; the language switcher still swaps to EN/HI instantly and remembers. */
let LANG = (function () {
  try {
    const saved = localStorage.getItem('shg:lang');
    if (saved && I18N[saved]) return saved;
    /* 13 Sep 2026 — Nepali first stays the default, but a phone that
       announces Hindi or Nepali itself (navigator.language) gets that
       straight away, before the admin default in init() is consulted. Any
       other device language (English, Gujarati, unknown) keeps Nepali. */
    const langs = (navigator.languages && navigator.languages.length) ? navigator.languages : [navigator.language || ''];
    for (let i = 0; i < langs.length; i++) {
      const c = String(langs[i] || '').toLowerCase().slice(0, 2);
      if (c === 'ne' || c === 'hi') { window.SHG_LANG_DETECTED = c; return c; }
    }
  } catch (e) {}
  return 'ne';
})();
